local classificationNames = {
    [1] = "Elite",
    [2] = "Rare Elite",
    [3] = "World Boss",
    [4] = "Rare",
}

local localeAliases = {
    enGB = "enUS",
}

function getMobClassification(name, locale)
    locale = locale or GetLocale()
    locale = localeAliases[locale] or locale
    local localizedData = mobClassifications[locale] or mobClassifications.enUS
    local classification = localizedData[name]

    return classificationNames[classification]
end

